func KnowledgeByRegion(region string) []Knowledge {
	out := []Knowledge{}
	for _, item := range KnowledgeArchive {
		if region == "" || item.Region == region {
			out = append(out, item)
		}
	}
	return out
}

func KnowledgeByMeaning(meaning string) []Knowledge {
	out := []Knowledge{}
	for _, item := range KnowledgeArchive {
		if meaning == "" || item.Meaning == meaning {
			out = append(out, item)
		}
	}
	return out
}
